#!/usr/bin/env julia

# Removes all files (likely) generated by invoking docs/make.jl

const DIR = @__DIR__
const ARTIFACTS = String[]

append!(
    ARTIFACTS,
    # Untracked files in build directory
    eachline(`git ls-files --other --directory $(joinpath(DIR, "build"))`),
    # Untracked files generated by Literate.jl and by copy_assets.jl
    let generated_output = joinpath.(DIR, "src", ["examples", "assets"])
        eachline(`git ls-files --other --directory $(generated_output)`)
    end,
)

for artifact in ARTIFACTS
    @info "Removing $artifact"
    rm(artifact; recursive = true, force = true)
end
